#include <stdio.h>
struct Point {
    int x;
    int y;
};
int main(void) {
    struct Point p, q;
    scanf("%d %d %d %d", &p.x, &p.y, &q.x, &q.y);
    int dx = q.x - p.x;
    int dy = q.y - p.y;
    printf("%d\n", dx * dx + dy * dy);
    return 0;
}

#include <stdio.h>
struct Student {
    char name[21];
    int age;
};
int main(void) {
    int n;
    scanf("%d", &n);
    struct Student s[100];
    int best = 0;
    for (int i = 0; i < n; i++) {
        scanf("%20s %d", s[i].name, &s[i].age);
        if (s[i].age > s[best].age) {
            best = i;
        }
    }
    printf("%s\n", s[best].name);
    return 0;
}
